const NO_SWORD = new Set(['rel-bidam-yushin']);

/** Third-pass refs exactly as attached; add-image-slots merges the canon portraits on top. */
const REFS = {
	'rel-mu-euija': ['/ch_mu.png', '/ch_euija_young.png', '/pl_sabi_palace.png'],
	'rel-chunchu-bupmin': ['/ch_chunchu.png', '/ch_bupmin_child.png', '/pl_eastern_palace.png'],
	'rel-yushin-bupmin': ['/ch_bupmin_hwarang.png', '/ch_kim_yushin.png'],
	'rel-bupmin-gotaso': ['/ch_bupmin_child.png', '/ch_gotaso.png', '/bn_gotaso.png'],
	'rel-seohyeon-yushin': ['/ch_kim_yushin_hwarang.png', '/ch_kim_seohyun.png', '/ar_lamellar_steel.png'],
	'rel-bidam-sukwon': ['/ch_bidam_hwarang.png', '/ch_bidam_old.png', '/pl_moryang.png'],
	'rel-yongsu-chunchu': ['/ch_chunchu_hwarang.png', '/ch_yongsu.png'],
	'rel-sunduk-jinduk': ['/ch_sunduk_old.png', '/ch_jinduk.png', '/bn_sunduk.png'],
	'rel-chunmyung-chunchu': ['/ch_chunmyung.png', '/ch_chunchu.png', '/bn_chunmyung.png'],
	'rel-jumong-sosuno': ['/ch_sosuno.png', '/ch_dongmyung.png', '/bn_sosuno.png'],
	'rel-euija-gyebek': ['/ch_buyeo_euija.png', '/ch_gyebek.png', '/ar_lamellar_steel.png', '/sw_bidam.png']
};

const manifest = JSON.parse(fs.readFileSync(MANIFEST, 'utf8'));
for (const item of manifest) {
	const body = SCENES[item.id];
	if (!body) throw new Error(`no scene for ${item.id}`);
	item.scene = `${OPEN} ${body} ${CLOSE}`;
	if (ALTS[item.id]) item.alt = ALTS[item.id];
	if (REFS[item.id]) item.refs = [...REFS[item.id]];
	if (NO_SWORD.has(item.id)) {
		item.refs = (item.refs ?? []).filter((r) => r !== '/sw_bidam.png');
		if (item.canon && typeof item.canon === 'object') delete item.canon.sword;
	}
	delete item.prompt;
}
fs.writeFileSync(MANIFEST, JSON.stringify(manifest, null, '\t') + '\n');
console.log(`rewrote ${manifest.length} scenes`);
